window.RP_SESSION={"id":"S-15042067edb8","messages":[{"id":"RP-III-0184176","time":"2026-09-20T00:25:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“ …모험이라니, 엘레나? 조금 더 자세히 말해주렴. ”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184177","time":"2026-09-20T00:26:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"말 그대로예요, 조금 더 많은 사람을 돕고 싶어서요…. 물론, 제가 없으면 농장 일이 조금 곤란해질 걸 알지만… 동생들도 있잖아요.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184178","time":"2026-09-20T00:28:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“ 엘레나, 그래. 네 꿈이 있으니 존중한다만 너무 위험한 일이잖니. 다른 일을 할 수는 없을까? 더 안전하게… 다른 사람들을 돕자, 응? ”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184179","time":"2026-09-20T00:30:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“ 엘레나, 매일 마을에 있는 도서관까지 가서… 그리 이야기를 들어대더니, 요상한 꿈이 생겼구나. 그런 건 우리랑 상관이 없는 일이란다…. ”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184180","time":"2026-09-20T00:30:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"이상하게 들리고, 걱정해서 하시는 말씀이신 거 알아요…! 하지만, 저는…….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184181","time":"2026-09-20T00:31:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“ 엘레나, 세상은 위험하단다. 너같이 여린 것이, 어찌 밖에서 그리 지내겠니. 너는… 너는…… ”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184182","time":"2026-09-20T00:32:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…알아요, 큰아빠. 하지만-\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184183","time":"2026-09-20T00:32:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“ 너는 마을에서도 크게 적응하지 못했잖니. ”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184184","time":"2026-09-20T00:33:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“ 남자애들이, 네게 험담을 한 것 땜에 연애는 꿈만 꾸던 애가 무슨 모험을 나가겠다는 게냐. ”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184185","time":"2026-09-20T00:33:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184186","time":"2026-09-20T00:35:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“ 엘레나, 큰아빠는 널 걱정해서 하시는 말씀이잖니. 엄마는, 엄마는 그냥… 너가 안전한 일을 하면 좋겠어. 응? ”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184187","time":"2026-09-20T00:36:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“ 우리 딸이 뭐가 아쉬워서, 그런 위험한 일을 해. 농장 일도 좋아했잖아…? 농장 일이 싫은 거면, 마을에서 다른 일거리를 얻어도……. ”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184188","time":"2026-09-20T00:38:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"……저도 알아요. 제가, 제가… 제가…. 그치만, 그치만… 저 잘해볼게요. 걱정하지 않으시게… 잘 지낼게요. 네?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184189","time":"2026-09-20T00:39:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"우리 집에서, 출가한 사람이 없다지만… 제가, 제가 첫 번째가 될 수도 있는 거잖아요…?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184190","time":"2026-09-20T00:39:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“ 그만하거라, 엘레나! 지금 가족을 버리겠다는 말을 하는 거나 다를 바가 없지 않냐! 뭉쳐야 사는 것이야. 혼자면 죽어! ”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184191","time":"2026-09-20T00:41:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“ 마을에서 고작, 고작 사내놈들이 네게… 뭐, 뭐? 덩치가 소 같다, 뭐 그런 말에 펑펑 울어댔으면서! 개꿈은 꾸지 말아라! ”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184192","time":"2026-09-20T00:41:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"……할아버지, 저는….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184193","time":"2026-09-20T00:42:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“ 네가 정, 정 그렇게 가고 싶으면 가라. 근데, 근데…! 기억해라. 이 할아비는 응원 못 한다. ”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184194","time":"2026-09-20T00:43:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“ ……미안, 엘레나. 큰엄마도 이번에는 반대야. 너무 위험하구나…. 너, 이제 슬슬 결혼을 생각할 나이 아니니…? ”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184195","time":"2026-09-20T00:45:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“ 엘레나…. 마을에 또래 남자들이 싫어서 그런 거야? 그런 거라면 다른 방법도…… ”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184196","time":"2026-09-20T00:46:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"아냐, 그런 게 아냐…! 그런, 그런 단순한 이유가 아냐….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184197","time":"2026-09-20T00:46:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"……마을에는, 제가 있을 자리가 아닌 것만 같아요. 그러니, 그러니까….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184198","time":"2026-09-20T00:47:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"제가, 있을 곳을 찾아서… 네…? 더 많은 사람을 도우면서, 그렇게…\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184199","time":"2026-09-20T00:47:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"더 많은 사람을 돕고, 올게요…. 약속할게요, 건강하게 돌아오겠다고 그렇게…….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184200","time":"2026-09-20T00:48:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"전 착한 딸이잖아요. 거짓말은 안 하잖아요….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184201","time":"2026-09-20T00:49:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"그때의 그 눈빛들, 마지못해 허락해 주시던 부모님… 도끼를 주시던, 걱정의 눈빛.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184202","time":"2026-09-20T00:50:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“…엘레나? 그 치즈 만들던 애? 아, 걔는 좀… 너무 흔하게 생겼지 않냐? 덩치도 무슨, 젖소 같잖아?”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184203","time":"2026-09-20T00:51:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“젖소는, 야! 아니, 걔는 어째 그러면 지가 돌보는 거랑 똑같은 거잖아! 미친 거 아냐, 아- 나는 목장 일 하는 여자는 안 만나야겠다.”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184204","time":"2026-09-20T00:52:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"“난 좀 얌전한 여자가 좋단 말이지. 엘레나는 나도 좀….”","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184205","time":"2026-09-20T00:52:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"...","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184206","time":"2026-09-20T00:52:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"...","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184207","time":"2026-09-20T00:52:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"...","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184208","time":"2026-09-20T00:53:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"꿈에서 깨어나야지, 엘레나.\n옛 생각은 그만하고.\n네가 어떤 마음으로 모험을 시작했는지 기억해.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184209","time":"2026-09-20T00:53:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"고향에 당당하게 돌아가고 싶지 않아?","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184210","time":"2026-09-20T00:54:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"……돌아가야지. 보란 듯이, 잘 살아서… 가야지…. 그렇게 또, 살아야지….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184211","time":"2026-09-20T00:54:00+09:00","room":"RP III","name":"엘레나 레지아노 / 과거 가족·마을 사람들","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0184212","time":"2026-09-20T00:54:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
